solution.solution.cpp:
#include <algorithm>
#include <cctype>
#include <cstdint>
#include <optional>
#include <sstream>
#include <string>
#include <vector>

struct PatchSpec
{
    std::string name;
    std::optional<std::size_t> offset;
    std::string pattern;
    std::size_t at{ 0 };
    std::vector<std::uint8_t> original, replacement;
};

class PatchSet
{
public:
    bool parse(const std::string& text, std::string& error)
    {
        list.clear();
        std::istringstream in{ text };
        std::string raw;
        int number{ 0 };
        while (std::getline(in, raw))
        {
            ++number;
            const std::string line{ trim(raw) };
            if (line.empty() || line[0] == '#') continue;
            if (line.front() == '[' && line.back() == ']') { list.push_back({}); list.back().name = line.substr(1, line.size() - 2); continue; }
            const std::size_t colon{ line.find(':') };
            const std::string key{ trim(line.substr(0, colon == std::string::npos ? line.size() : colon)) };
            const std::string value{ colon == std::string::npos ? "" : trim(line.substr(colon + 1)) };
            const std::string where{ "line " + std::to_string(number) + ": " };
            if (key != "offset" && key != "pattern" && key != "at" && key != "original" && key != "replacement") { error = where + "unknown key"; return false; }
            if (list.empty()) { error = where + "key outside a patch"; return false; }
            PatchSpec& p{ list.back() };
            if (key == "offset") p.offset = static_cast<std::size_t>(std::stoull(value, nullptr, 0));
            else if (key == "pattern") p.pattern = value;
            else if (key == "at") p.at = static_cast<std::size_t>(std::stoull(value));
            else
            {
                const auto bytes{ hexBytes(value) };
                if (!bytes) { error = where + "bad bytes"; return false; }
                (key == "original" ? p.original : p.replacement) = *bytes;
            }
        }
        for (const PatchSpec& p : list)
        {
            if (p.offset.has_value() == !p.pattern.empty()) { error = "patch " + p.name + ": needs offset or pattern"; return false; }
            if (p.original.empty() || p.original.size() != p.replacement.size()) { error = "patch " + p.name + ": original and replacement differ"; return false; }
        }
        return true;
    }

    const std::vector<PatchSpec>& patches() const { return list; }

    std::optional<std::size_t> locate(const std::vector<std::uint8_t>& code, const PatchSpec& p) const
    {
        if (p.offset) return *p.offset;
        const auto pattern{ parsePattern(p.pattern) };
        if (!pattern || pattern->empty() || pattern->size() > code.size()) return std::nullopt;
        std::optional<std::size_t> found;
        for (std::size_t i{ 0 }; i + pattern->size() <= code.size(); ++i)
        {
            bool match{ true };
            for (std::size_t k{ 0 }; k < pattern->size() && match; ++k) match = !(*pattern)[k] || code[i + k] == *(*pattern)[k];
            if (!match) continue;
            if (found) return std::nullopt;
            found = i;
        }
        if (!found) return std::nullopt;
        return *found + p.at;
    }

    std::vector<std::string> check(const std::vector<std::uint8_t>& code) const
    {
        std::vector<std::string> problems;
        std::vector<std::optional<std::size_t>> where;
        for (const PatchSpec& p : list)
        {
            const auto at{ locate(code, p) };
            where.push_back(at);
            if (!at) { problems.push_back(p.name + ": not found"); continue; }
            if (!holds(code, *at, p.original)) problems.push_back(p.name + ": original bytes differ");
        }
        for (std::size_t i{ 0 }; i < list.size(); ++i)
            for (std::size_t j{ i + 1 }; j < list.size(); ++j)
                if (where[i] && where[j] && *where[i] < *where[j] + list[j].original.size() && *where[j] < *where[i] + list[i].original.size())
                    problems.push_back(list[i].name + " and " + list[j].name + " overlap");
        return problems;
    }

    bool applyAll(std::vector<std::uint8_t>& code) const
    {
        if (!check(code).empty()) return false;
        std::vector<std::size_t> at;
        for (const PatchSpec& p : list) at.push_back(*locate(code, p));
        for (std::size_t i{ 0 }; i < list.size(); ++i) std::copy(list[i].replacement.begin(), list[i].replacement.end(), code.begin() + static_cast<std::ptrdiff_t>(at[i]));
        return true;
    }

    bool revertAll(std::vector<std::uint8_t>& code) const
    {
        std::vector<std::size_t> at;
        for (const PatchSpec& p : list)
        {
            // A pattern may no longer match once patched, so a pattern patch is found by its replacement in place of the original.
            std::optional<std::size_t> where{ p.offset };
            if (!where)
            {
                PatchSpec patched{ p };
                patched.pattern = patchedPattern(p);
                where = locate(code, patched);
            }
            if (!where || !holds(code, *where, p.replacement)) return false;
            at.push_back(*where);
        }
        for (std::size_t i{ 0 }; i < list.size(); ++i) std::copy(list[i].original.begin(), list[i].original.end(), code.begin() + static_cast<std::ptrdiff_t>(at[i]));
        return true;
    }

private:
    std::vector<PatchSpec> list;

    static std::string trim(const std::string& s)
    {
        std::size_t a{ 0 }, b{ s.size() };
        while (a < b && std::isspace(static_cast<unsigned char>(s[a]))) ++a;
        while (b > a && std::isspace(static_cast<unsigned char>(s[b - 1]))) --b;
        return s.substr(a, b - a);
    }

    static std::optional<std::vector<std::uint8_t>> hexBytes(const std::string& text)
    {
        std::vector<std::uint8_t> out;
        std::istringstream in{ text };
        std::string token;
        while (in >> token)
        {
            if (token.size() != 2 || !std::isxdigit(static_cast<unsigned char>(token[0])) || !std::isxdigit(static_cast<unsigned char>(token[1]))) return std::nullopt;
            out.push_back(static_cast<std::uint8_t>(std::stoul(token, nullptr, 16)));
        }
        if (out.empty()) return std::nullopt;
        return out;
    }

    static std::optional<std::vector<std::optional<std::uint8_t>>> parsePattern(const std::string& text)
    {
        std::vector<std::optional<std::uint8_t>> out;
        std::istringstream in{ text };
        std::string token;
        while (in >> token)
        {
            if (token == "?" || token == "??") { out.push_back(std::nullopt); continue; }
            if (token.size() != 2 || !std::isxdigit(static_cast<unsigned char>(token[0])) || !std::isxdigit(static_cast<unsigned char>(token[1]))) return std::nullopt;
            out.push_back(static_cast<std::uint8_t>(std::stoul(token, nullptr, 16)));
        }
        return out;
    }

    // The pattern as it reads after the patch: the replaced bytes become wildcards.
    static std::string patchedPattern(const PatchSpec& p)
    {
        const auto tokens{ parsePattern(p.pattern) };
        if (!tokens) return p.pattern;
        std::string out;
        for (std::size_t i{ 0 }; i < tokens->size(); ++i)
        {
            const bool replaced{ i >= p.at && i < p.at + p.replacement.size() };
            static const char* const HEX{ "0123456789ABCDEF" };
            if (replaced || !(*tokens)[i]) out += "?? ";
            else { out += HEX[*(*tokens)[i] >> 4]; out += HEX[*(*tokens)[i] & 0xF]; out += ' '; }
        }
        return out;
    }

    static bool holds(const std::vector<std::uint8_t>& code, std::size_t at, const std::vector<std::uint8_t>& bytes)
    {
        return at <= code.size() && code.size() - at >= bytes.size() && std::equal(bytes.begin(), bytes.end(), code.begin() + static_cast<std::ptrdiff_t>(at));
    }
};

unitTests:
using Bytes = std::vector<std::uint8_t>;
static Bytes build()
{
    Bytes b(0x40, 0xCC);
    const Bytes intro{ 0x84, 0xC0, 0x74, 0x0C };
    const Bytes damage{ 0x2B, 0xC3, 0x89, 0x47, 0x1C, 0x48, 0x8B, 0x0D, 0x6A, 0x2F, 0x01, 0x00 };
    std::copy(intro.begin(), intro.end(), b.begin() + 0x10);
    std::copy(damage.begin(), damage.end(), b.begin() + 0x20);
    return b;
}
static const std::string FILE_TEXT{
    "# patches for a test build\n"
    "[skip-intro]\n"
    "offset: 0x12\n"
    "original: 74 0C\n"
    "replacement: EB 0C\n"
    "\n"
    "[no-cooldown]\n"
    "pattern: 2B C3 89 47 ?? 48 8B 0D\n"
    "at: 2\n"
    "original: 89 47 1C\n"
    "replacement: 90 90 90\n" };

TEST("parsing") {
    PatchSet set;
    std::string error;
    CHECK(set.parse(FILE_TEXT, error));
    CHECK_EQ(set.patches().size(), 2u);
    if (set.patches().size() != 2) return;
    CHECK_EQ(set.patches()[0].offset.value_or(0), 0x12u);
    CHECK_EQ(set.patches()[1].at, 2u);
    CHECK(set.patches()[1].replacement == (Bytes{ 0x90, 0x90, 0x90 }));
}
TEST("parse errors") {
    PatchSet set;
    std::string error;
    CHECK(!set.parse("[a]\noffset: 1\nsize: 2\n", error)); CHECK_EQ(error, std::string("line 3: unknown key"));
    CHECK(!set.parse("offset: 1\n", error)); CHECK_EQ(error, std::string("line 1: key outside a patch"));
    CHECK(!set.parse("[a]\noffset: 1\noriginal: 7\nreplacement: EB\n", error)); CHECK_EQ(error, std::string("line 3: bad bytes"));
    CHECK(!set.parse("[a]\noriginal: 74\nreplacement: EB\n", error)); CHECK_EQ(error, std::string("patch a: needs offset or pattern"));
    CHECK(!set.parse("[a]\noffset: 2\noriginal: 74 0C\nreplacement: EB\n", error)); CHECK_EQ(error, std::string("patch a: original and replacement differ"));
}
TEST("locating") {
    PatchSet set;
    std::string error;
    set.parse(FILE_TEXT, error);
    const Bytes code{ build() };
    CHECK_EQ(set.locate(code, set.patches()[1]).value_or(0), 0x22u);
    Bytes twice{ code };
    std::copy(code.begin() + 0x20, code.begin() + 0x28, twice.begin() + 0x30);
    CHECK(!set.locate(twice, set.patches()[1]).has_value());
}
TEST("apply and revert") {
    PatchSet set;
    std::string error;
    set.parse(FILE_TEXT, error);
    Bytes code{ build() };
    CHECK(set.check(code).empty());
    CHECK(set.applyAll(code));
    CHECK_EQ(code[0x12], 0xEB);
    CHECK(code[0x22] == 0x90 && code[0x24] == 0x90);
    CHECK(!set.applyAll(code));
    CHECK(set.revertAll(code));
    CHECK(code == build());
    CHECK(!set.revertAll(code));
}
TEST("problems stop everything") {
    PatchSet set;
    std::string error;
    set.parse(FILE_TEXT, error);
    Bytes other{ build() };
    other[0x13] = 0x10;
    other[0x20] = 0x29;
    CHECK_EQ(set.check(other), (std::vector<std::string>{ "skip-intro: original bytes differ", "no-cooldown: not found" }));
    const Bytes before{ other };
    CHECK(!set.applyAll(other));
    CHECK(other == before);
    PatchSet clash;
    clash.parse("[a]\noffset: 0x10\noriginal: 84 C0 74\nreplacement: 90 90 90\n[b]\noffset: 0x12\noriginal: 74 0C\nreplacement: EB 0C\n", error);
    CHECK_EQ(clash.check(build()), (std::vector<std::string>{ "a and b overlap" }));
}

